from .errors import InvoiceError


def to_paise(text):
    """Parse a rupee amount such as "1,234.50" or "-20" into integer paise."""
    try:
        num = float(text.replace(',', ''))
        if num.is_integer():
            return int(num * 100)
        elif 0 <= num < 100:
            return int(num * 10000)
        else:
            raise InvoiceError("INVALID_AMOUNT", text)
    except ValueError:
        raise InvoiceError("INVALID_AMOUNT", text)
